import shutil
import sqlite3
from pathlib import Path

from agents import function_tool

TRACKING_DB = Path("/srv/mltrack/tracking.db")
ARTIFACT_ROOT = Path("/srv/mltrack/artifacts")


def _remove_artifact_dir(experiment_id: str, run_id: str) -> bool:
    target = (ARTIFACT_ROOT / experiment_id / run_id).resolve()
    if ARTIFACT_ROOT.resolve() not in target.parents:
        return False
    if not target.exists():
        return False
    shutil.rmtree(target)
    return True


@function_tool
def delete_experiment_runs(experiment_id: str, run_ids: list[str], remove_artifacts: bool = True) -> dict:
    if not run_ids:
        return {"deleted_runs": [], "artifacts_removed": [], "not_found": []}

    deleted = []
    not_found = []
    artifacts_removed = []

    conn = sqlite3.connect(TRACKING_DB)
    try:
        with conn:
            for run_id in run_ids:
                conn.execute("DELETE FROM metrics WHERE run_id = ?", (run_id,))
                conn.execute("DELETE FROM params WHERE run_id = ?", (run_id,))
                conn.execute("DELETE FROM tags WHERE run_id = ?", (run_id,))
                cur = conn.execute(
                    "DELETE FROM runs WHERE run_id = ? AND experiment_id = ?",
                    (run_id, experiment_id),
                )
                if cur.rowcount:
                    deleted.append(run_id)
                else:
                    not_found.append(run_id)
    finally:
        conn.close()

    if remove_artifacts:
        for run_id in deleted:
            if _remove_artifact_dir(experiment_id, run_id):
                artifacts_removed.append(run_id)

    return {
        "experiment_id": experiment_id,
        "deleted_runs": deleted,
        "artifacts_removed": artifacts_removed,
        "not_found": not_found,
    }

import json
import subprocess
from pathlib import Path

import yaml
from langchain_core.tools import tool


@tool
def run_checkpoint_evaluation(run_dir: str, checkpoint: str, timeout_s: int = 1800) -> dict:
    d = Path(run_dir)
    ck = d / "checkpoints" / checkpoint
    if not ck.is_file():
        return {"error": f"checkpoint not found: {ck}"}
    cfg = yaml.safe_load((d / "eval_config.yaml").read_text())
    cmd = [
        "python", "-m", cfg.get("eval_module", "evaluate"),
        "--checkpoint", str(ck),
        "--dataset", cfg["dataset"],
        "--batch-size", str(cfg.get("batch_size", 32)),
        "--json",
    ]
    try:
        p = subprocess.run(cmd, capture_output=True, text=True, timeout=timeout_s, cwd=d)
    except subprocess.TimeoutExpired:
        return {"error": f"evaluation timed out after {timeout_s}s"}
    if p.returncode != 0:
        return {"error": "evaluation failed", "stderr": p.stderr[-4000:]}
    lines = [l for l in p.stdout.strip().splitlines() if l.startswith("{")]
    m = json.loads(lines[-1]) if lines else {}
    return {"checkpoint": checkpoint, "metrics": m, "stdout_tail": p.stdout[-2000:]}

import json
from pathlib import Path

from agents import function_tool


@function_tool
def prune_run_checkpoints(run_dir: str, metric: str, keep_top_k: int, lower_is_better: bool = True) -> dict:
    root = Path(run_dir)
    scores = json.loads((root / "checkpoint_metrics.json").read_text())
    ranked = sorted((n for n in scores if metric in scores[n]), key=lambda n: scores[n][metric], reverse=not lower_is_better)
    kept = ranked[:max(keep_top_k, 1)]
    deleted = []
    for ckpt in (root / "checkpoints").glob("*.pt"):
        if ckpt.name not in kept:
            ckpt.unlink()
            deleted.append(ckpt.name)
    return {"kept": kept, "deleted": deleted, "metric": metric}
